<script>
  document.addEventListener('DOMContentLoaded', function() {
    const stepsData = {
      1: {
        title: "Discovery",
        items: [{
          title: "Analyze Current Ads & Metrics",
          desc: "We review your historic campaign data, tracking setup, and ad performance to identify leaks and opportunities."
        }, {
          title: "Define Target Personas & KPI",
          desc: "We establish clear KPIs and outline the demographics, interests, and behaviors of your ideal buyers."
        }]
      },
      2: {
        title: "Audience Build",
        items: [{
          title: "Setup Custom & Lookalike Audiences",
          desc: "We build warm custom audiences (web traffic, video viewers) and lookalikes to find high-intent prospects."
        }, {
          title: "Pixel & API Configuration",
          desc: "We integrate Facebook Pixel & Conversions API to track user actions securely and ensure accurate attribution."
        }]
      },
      3: {
        title: "Creative",
        items: [{
          title: "Ad Copy & Messaging Strategy",
          desc: "We write persuasive headlines and ad copy tailored to address your target audience's pain points."
        }, {
          title: "Visual Design & Video Production",
          desc: "We produce high-impact graphics and short-form videos optimized for both mobile and feed placements."
        }]
      },
      4: {
        title: "Campaign Setup",
        items: [{
          title: "Define Campaign & Bidding Structure",
          desc: "We setup clean campaign structures with optimal bidding models (CBO/ABO) to get you the lowest cost per action."
        }, {
          title: "Creative Asset Integration",
          desc: "We launch dynamic and single creative ad variations within structured ad sets to avoid overlap."
        }]
      },
      5: {
        title: "Optimise",
        items: [{
          title: "A/B Testing Variables",
          desc: "We constantly test creatives, copy variations, and audience placements to refine the overall campaign performance."
        }, {
          title: "Budget Reallocation",
          desc: "We scale high-performing ad sets and shut down underperforming ones to maximize your ROAS."
        }]
      },
      6: {
        title: "Report",
        items: [{
          title: "Performance Reporting",
          desc: "We build custom dashboards showing CPL, CPC, ROAS, and conversions so you always know where your budget is going."
        }, {
          title: "Strategic Optimization",
          desc: "We present monthly insights and align on strategic changes to continuously improve results."
        }]
      },
      7: {
        title: "Scale",
        items: [{
          title: "Scale Winning Campaigns",
          desc: "We scale the budget of winning campaigns vertically and expand targeting horizontally to reach larger audiences."
        }, {
          title: "Creative Refresh",
          desc: "We introduce fresh ad variations regularly to prevent ad fatigue and maintain high conversion rates."
        }]
      }
    };
    const stepNodes = document.querySelectorAll('.process-step-node');
    const activeLine = document.querySelector('.process-timeline-line-active');
    const titleElement = document.getElementById('active-step-title');
    const contentArea = document.getElementById('process-step-content-area');

    function updateStep(stepIndex) {
      // Update nodes states
      stepNodes.forEach(node => {
        const nodeStep = parseInt(node.getAttribute('data-step'));
        if (nodeStep <= stepIndex) {
          node.classList.add('active');
        } else {
          node.classList.remove('active');
        }
      });
      // Update active line progress
      if (activeLine && stepNodes.length > 0) {
        const firstNode = stepNodes[0];
        const activeNode = stepNodes[stepIndex - 1];
        if (firstNode && activeNode) {
          const firstCenter = firstNode.offsetLeft + (firstNode.offsetWidth / 2);
          const activeCenter = activeNode.offsetLeft + (activeNode.offsetWidth / 2);
          activeLine.style.left = firstCenter + 'px';
          activeLine.style.width = (activeCenter - firstCenter) + 'px';
        }
      }
      // Update content
      const stepData = stepsData[stepIndex];
      if (stepData) {
        if (titleElement) {
          titleElement.textContent = stepData.title;
        }
        let htmlContent = '';
        stepData.items.forEach(item => {
          htmlContent += `
                    
				<div class="process-card-item mb-4">
					<h4 class="text-white font-weight-bold mb-2">${item.title}</h4>
					<p class="process-card-desc mb-0">${item.desc}</p>
				</div>
                `;
        });
        if (contentArea) {
          contentArea.innerHTML = htmlContent;
        }
      }
    }
    // Add click listeners
    stepNodes.forEach(node => {
      node.addEventListener('click', function() {
        const stepIndex = parseInt(this.getAttribute('data-step'));
        updateStep(stepIndex);
      });
    });
    // Initialize first step
    updateStep(1);
  });
</script>
